strudelHints:
// Low threat: s('metal:1').gain(0.2).slow(4)
// Medium threat: s('metal:1').gain(0.3).slow(2)
// High threat: s('metal:1').gain(0.4)
// Maximum: s('metal:1').gain(0.5).fast(2)

strudelIdioms.example:
stack(
  // Stealth layers (always on)
  s('noise').gain(0.05).room(0.9).lpf(200),
  note('d1').s('sine').gain(0.15).lpf(80),
  // Tension adds
  s('metal:1').gain(0.2).room(0.3),
  // Combat adds
  s('bd').gain(0.6)...
)

examplePatterns.code:
setcpm(120)
stack(
  // STEALTH BASE (always on)
  note('d1 d1 ~ ~ d1 ~ ~ ~').s('sine').gain(0.15).lpf(100).room(0.5),
  s('noise').gain(0.04).room(0.9).lpf(300).slow(24),
  // TENSION LAYER (adds for tension+)
  s('metal:1').gain(0.2).room(0.3).struct('~ x ~ ~ ~ x ~ ~ ~ x ~ ~ ~ ~ x ~'),
  note('d2 ~ ~ f2 ~ d2 ~ ~').s('sawtooth').lpf(400).gain(0.2).room(0.3),
  // COMBAT LOW (adds for combat+)
  s('bd').gain(0.6).room(0.15).struct('x ~ ~ x ~ x ~ ~ x ~ ~ x ~ ~ x ~'),
  // COMBAT HIGH (adds for full combat)
  s('metal:2 metal:3').gain(0.35).room(0.2).struct('x x ~ x ~ x x ~ x x ~ x ~ x ~ x'),
  s('noise').gain(0.08).lpf(2000).hpf(500).room(0.2)
)
